import React, { useEffect, useState } from 'react'
import { useAuth } from '../context/AuthContext'

import axiosInstance from '../api/axiosInstance'

export function MyTeam() {
    const [team, setTeam] = useState('')
    const { user } = useAuth()
    const [myTeam, setMyTeam] = useState(null)
    const [playerId, setPlayerId] = useState('')
    async function handleTeamCreate(e) {
        e.preventDefault()
        const response = await axiosInstance.post("/team/create", { name: team })

    }

    useEffect(() => {
        async function fetchMyTeam() {
            try {
                const response = await axiosInstance.get("/team/myteam")
                setMyTeam(response.data);

            }
            catch (error) {
                console.log(error.response.data);

            }

        }
        fetchMyTeam()

    }, [])

    async function handlePlayerTeam(e) {
        try {
            e.preventDefault()
            const response = await axiosInstance.put('/team/player/'+myTeam._id, { playerId })
            setMyTeam(response.data)
            setPlayerId('')

        }
        catch (error) {
            console.log(error);

        }
    }

    async function handleRemovePlayer(){
        try{

        }
        catch(error){
            log
        }
    }
    return (
        <div><h1>Team's</h1>

            <form onSubmit={handleTeamCreate}>
                <label >Team Name</label><input type="text" onChange={(e) => { setTeam(e.target.value) }} value={team} />
                <button>Create</button>
            </form>
            <div>
                <h1>Add Player</h1>
                <form onSubmit={handlePlayerTeam} >
                    <label>Player</label>
                    <input type="text" value={playerId} onChange={(e) => { setPlayerId(e.target.value) }} />
                    <button >ADD</button>
                </form>
            </div>

            <div><h1>My Team</h1>
                {
                    myTeam ? (
                        <div><p>{myTeam.name}</p>
                            <p>{myTeam.players.length}</p>
                        </div>
                    ) : (
                        <p>You have no team</p>
                    )
                }

            </div>


        </div>
    )
}
